return-response.set-body:
@{
                var r = new Random();
                var answers = new[] {
                    "APIOps significa trattare la configurazione di API Management come codice: repository, pull request, pipeline.",
                    "Il dry-run mostra cosa cambierebbe in APIM prima di pubblicare: PUT, DELETE, SKIP.",
                    "Gli override per ambiente sostituiscono URL e segreti al publish: stessi artefatti, valori diversi.",
                    "Un AI gateway limita i token, misura i consumi, mette in cache le risposte simili e filtra i contenuti.",
                    "La CLI apiops ha quattro comandi: init, extract, publish e apic."
                };
                var content = answers[r.Next(answers.Length)];
                var prompt = r.Next(20, 60); var completion = content.Length / 4;
                return "{\"id\":\"chatcmpl-" + context.RequestId.ToString("N").Substring(0, 12) + "\",\"object\":\"chat.completion\",\"created\":" + DateTimeOffset.UtcNow.ToUnixTimeSeconds() + ",\"model\":\"mock-s4d-1\",\"choices\":[{\"index\":0,\"message\":{\"role\":\"assistant\",\"content\":\"" + content + "\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":" + prompt + ",\"completion_tokens\":" + completion + ",\"total_tokens\":" + (prompt + completion) + "}}";
            }
